// Advanced version: Splits multiple cart items into separate line items
// Handles both single cart items and arrays of cart items

const items = $input.all();
const outputItems = [];

for (const item of items) {
  try {
    // Extract the body data (webhook payload)
    const data = item.json.body || item.json;

    // Check if cartItem is an array or single object
    let cartItems = [];

    if (data.cartItem) {
      // If cartItem is an array, use it directly
      if (Array.isArray(data.cartItem)) {
        cartItems = data.cartItem;
      } else {
        // If single item, wrap in array
        cartItems = [data.cartItem];
      }
    } else if (data.cartItems && Array.isArray(data.cartItems)) {
      // Alternative field name
      cartItems = data.cartItems;
    } else {
      // No cart items found, create one from the main data
      cartItems = [{
        id: data.itemId,
        itemName: data.deviceType,
        itemDescription: data.itemDescription,
        itemCategory: data.itemCategory,
        itemNature: data.itemNature,
        quantity: data.quantityOrdered,
        itemUrl: data.itemUrl
      }];
    }

    // Create a line item for each cart item
    cartItems.forEach((cartItem, index) => {
      const lineItem = {
        // Order-level information (same for all line items)
        orderId: data.orderId,
        autoGeneratedOrderId: data.autoGeneratedOrderId,
        uniqueOrderRecordId: data.uniqueOrderRecordId,
        dateOrdered: data.dateOrdered,
        dateOrderedISO: data.dateOrderedISO,
        totalQuantity: data.totalQuantity,
        cartLength: data.cartLength || cartItems.length,

        // Line number: use provided lineNumber or generate from index
        lineNumber: data.lineNumber || (index + 1),
        lineIndex: index, // 0-based index

        // Customer/Delivery information
        contractorCompany: data.contractorCompany,
        region: data.region,
        technician: data.technician,
        orderedBy: data.orderedBy,
        orderLocation: data.orderLocation,
        deliverToPart: data.deliverToPart,
        onBehalfOf: data.onBehalfOf,
        popId: data.popId,
        cellPhoneNumber: data.cellPhoneNumber,

        // Recipient information (if delivery to third party)
        recipientName: data.recipientName,
        recipientCompanyName: data.recipientCompanyName,
        recipientAddress: data.recipientAddress,
        recipientContactNumber: data.recipientContactNumber,
        recipientEmail: data.recipientEmail,

        // Line Item specific information (from this specific cartItem)
        itemId: cartItem.id,
        itemName: cartItem.itemName,
        itemDescription: cartItem.itemDescription,
        itemCategory: cartItem.itemCategory,
        itemNature: cartItem.itemNature,
        deviceType: cartItem.itemName || cartItem.deviceType,
        quantityOrdered: cartItem.quantity,
        itemUrl: cartItem.itemUrl,

        // Calculated fields
        isFirstLine: index === 0,
        isLastLine: index === (cartItems.length - 1),

        // Metadata
        webhookUrl: item.json.webhookUrl,
        executionMode: item.json.executionMode,
        processedAt: new Date().toISOString(),

        // Preserve headers if needed
        _headers: item.json.headers,

        // Full original data (for reference if needed)
        _originalFormData: data.formData,
        _originalCartItem: cartItem
      };

      outputItems.push({
        json: lineItem
      });
    });

  } catch (error) {
    // If there's an error, output the error along with the original item
    outputItems.push({
      json: {
        error: error.message,
        errorStack: error.stack,
        errorDetails: 'Failed to process cart item',
        originalData: item.json,
        timestamp: new Date().toISOString()
      }
    });
  }
}

return outputItems;
